"""Inject entrance animations + transitions into the pptx generated by deck.js."""
import json, re, sys, zipfile, shutil
src, spec_path, out = sys.argv[1], sys.argv[2], sys.argv[3]
spec = json.load(open(spec_path))
ids = iter(range(10**6))

class Ctr:
    def __init__(s): s.n = 2
    def __call__(s): s.n += 1; return s.n

def tgt(spid): return f'<p:tgtEl><p:spTgt spid="{spid}"/></p:tgtEl>'
def setvis(c, spid):
    return (f'<p:set><p:cBhvr><p:cTn id="{c()}" dur="1" fill="hold"><p:stCondLst><p:cond delay="0"/></p:stCondLst></p:cTn>{tgt(spid)}'
            f'<p:attrNameLst><p:attrName>style.visibility</p:attrName></p:attrNameLst></p:cBhvr><p:to><p:strVal val="visible"/></p:to></p:set>')
def efx(c, spid, filt, dur):
    return f'<p:animEffect transition="in" filter="{filt}"><p:cBhvr><p:cTn id="{c()}" dur="{dur}"/>{tgt(spid)}</p:cBhvr></p:animEffect>'
def anim(c, spid, attr, a, b, dur, fa=False):
    v0 = f'<p:fltVal val="{a}"/>' if fa else f'<p:strVal val="{a}"/>'
    return (f'<p:anim calcmode="lin" valueType="num"><p:cBhvr additive="base"><p:cTn id="{c()}" dur="{dur}" fill="hold"/>{tgt(spid)}'
            f'<p:attrNameLst><p:attrName>{attr}</p:attrName></p:attrNameLst></p:cBhvr><p:tavLst><p:tav tm="0"><p:val>{v0}</p:val></p:tav>'
            f'<p:tav tm="100000"><p:val><p:strVal val="{b}"/></p:val></p:tav></p:tavLst></p:anim>')
FX = {  # name: (presetID, subtype, builder)
 'fade':  (10, 0, lambda c, s, d: setvis(c, s) + efx(c, s, 'fade', d)),
 'wipeR': (22, 2, lambda c, s, d: setvis(c, s) + efx(c, s, 'wipe(right)', d)),
 'flyR':  (2, 2, lambda c, s, d: setvis(c, s) + anim(c, s, 'ppt_x', '1+#ppt_w/2', '#ppt_x', d) + anim(c, s, 'ppt_y', '#ppt_y', '#ppt_y', d)),
 'flyL':  (2, 8, lambda c, s, d: setvis(c, s) + anim(c, s, 'ppt_x', '0-#ppt_w/2', '#ppt_x', d) + anim(c, s, 'ppt_y', '#ppt_y', '#ppt_y', d)),
 'flyB':  (2, 4, lambda c, s, d: setvis(c, s) + anim(c, s, 'ppt_x', '#ppt_x', '#ppt_x', d) + anim(c, s, 'ppt_y', '1+#ppt_h/2', '#ppt_y', d)),
 'zoom':  (53, 16, lambda c, s, d: setvis(c, s) + anim(c, s, 'ppt_w', '0', '#ppt_w', d, True) + anim(c, s, 'ppt_h', '0', '#ppt_h', d, True) + efx(c, s, 'fade', d)),
 'float': (42, 0, lambda c, s, d: setvis(c, s) + efx(c, s, 'fade', d) + anim(c, s, 'ppt_x', '#ppt_x', '#ppt_x', d) + anim(c, s, 'ppt_y', '#ppt_y+.1', '#ppt_y', d)),
}
TRANS = ['<p:transition spd="slow"><p:fade/></p:transition>', '<p:transition spd="slow"><p:push dir="l"/></p:transition>',
         '<p:transition spd="slow"><p:wipe dir="l"/></p:transition>', '<p:transition spd="slow"><p:cover dir="l"/></p:transition>']

def build_timing(items, kinds):
    c = Ctr()
    groups = []  # list of click groups -> list of subpars -> list of items
    for it in items:
        if it['trig'] == 'click' or not groups:
            groups.append([[it]])
        elif it['trig'] == 'with':
            groups[-1][-1].append(it)
        else:
            groups[-1].append([it])
    xml = []
    for gi, g in enumerate(groups):
        first_auto = gi == 0 and g[0][0]['trig'] != 'click'
        cond = '<p:cond delay="indefinite"/>' + ('<p:cond evt="onBegin" delay="0"><p:tn val="2"/></p:cond>' if first_auto else '')
        sub, t = [], 0
        for si, sp in enumerate(g):
            inner = []
            for k, it in enumerate(sp):
                pid, st, fn = FX[it['fx']]
                if k == 0:
                    nt = 'afterEffect' if (si > 0 or first_auto) else 'clickEffect'
                else:
                    nt = 'withEffect'
                ctn = c()
                inner.append(f'<p:par><p:cTn id="{ctn}" presetID="{pid}" presetClass="entr" presetSubtype="{st}" fill="hold" grpId="0" nodeType="{nt}">'
                             f'<p:stCondLst><p:cond delay="{it["delay"]}"/></p:stCondLst><p:childTnLst>{fn(c, it["spid"], it["dur"])}</p:childTnLst></p:cTn></p:par>')
            sub.append((t, inner))
            t += max(it['delay'] + it['dur'] for it in sp)
        # need ids in order: rebuild with proper nesting ids (ids only need to be unique)
        parts = ''.join(f'<p:par><p:cTn id="{c()}" fill="hold"><p:stCondLst><p:cond delay="{st}"/></p:stCondLst><p:childTnLst>{"".join(inn)}</p:childTnLst></p:cTn></p:par>' for st, inn in sub)
        xml.append(f'<p:par><p:cTn id="{c()}" fill="hold"><p:stCondLst>{cond}</p:stCondLst><p:childTnLst>{parts}</p:childTnLst></p:cTn></p:par>')
    bld = ''
    for spid in dict.fromkeys(it['spid'] for it in items):
        k = kinds[spid]
        if k == 'sp': bld += f'<p:bldP spid="{spid}" grpId="0" animBg="1"/>'
        elif k == 'graphicFrame': bld += f'<p:bldGraphic spid="{spid}" grpId="0"><p:bldAsOne/></p:bldGraphic>'
    return ('<p:timing><p:tnLst><p:par><p:cTn id="1" dur="indefinite" restart="never" nodeType="tmRoot"><p:childTnLst>'
            '<p:seq concurrent="1" nextAc="seek"><p:cTn id="2" dur="indefinite" nodeType="mainSeq"><p:childTnLst>'
            + ''.join(xml) +
            '</p:childTnLst></p:cTn><p:prevCondLst><p:cond evt="onPrev" delay="0"><p:tgtEl><p:sldTgt/></p:tgtEl></p:cond></p:prevCondLst>'
            '<p:nextCondLst><p:cond evt="onNext" delay="0"><p:tgtEl><p:sldTgt/></p:tgtEl></p:cond></p:nextCondLst></p:seq>'
            '</p:childTnLst></p:cTn></p:par></p:tnLst>' + (f'<p:bldLst>{bld}</p:bldLst>' if bld else '') + '</p:timing>')

PPR = re.compile(r'<a:pPr\b[^>]*?(?:/>|>.*?</a:pPr>)', re.S)
def fix_para(m):
    p = m.group(0)
    pprs = list(PPR.finditer(p))
    if not pprs: return p
    first = pprs[0].group(0)
    body = PPR.sub('', p)                      # pptxgenjs repeats pPr between runs; keep one
    if 'rtl=' not in first.split('>')[0]:      # LTR text must say so: the deck is RTL by default
        first = first.replace('<a:pPr', '<a:pPr rtl="0"', 1)
    return body.replace('<a:p>', '<a:p>' + first, 1)
def fix_paras(x):
    return re.sub(r'<a:p>.*?</a:p>', fix_para, x, flags=re.S)

zin = zipfile.ZipFile(src)
import hashlib
canon, drop = {}, set()
for n in zin.namelist():
    if n.startswith('ppt/media/'):
        h = hashlib.md5(zin.read(n)).hexdigest()
        if h in canon: drop.add(n); canon[n] = canon[h]
        else: canon[h] = n; canon[n] = n

zout = zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED)
for info in zin.infolist():
    if info.filename in drop: continue
    data = zin.read(info.filename)
    if info.filename.endswith('.rels'):
        x = data.decode('utf8')
        x = re.sub(r'\.\./media/([^"]+)', lambda mm: '../media/' + canon['ppt/media/' + mm.group(1)].split('/')[-1], x)
        data = x.encode('utf8')
    m = re.fullmatch(r'ppt/slides/slide(\d+)\.xml', info.filename)
    if m:
        idx = int(m.group(1)) - 1
        x = data.decode('utf8')
        # renumber every cNvPr id uniquely (pptxgenjs table ids can collide)
        counter = iter(range(2, 100000))
        x = re.sub(r'<p:cNvPr id="\d+"', lambda _: f'<p:cNvPr id="{next(counter)}"', x)
        x = fix_paras(x)
        kinds, names = {}, {}
        for mm in re.finditer(r'<p:(sp|pic|graphicFrame)>\s*<p:nv\w+>\s*<p:cNvPr id="(\d+)" name="([^"]*)"', x):
            kinds[mm.group(2)] = mm.group(1); names[mm.group(3)] = mm.group(2)
        items = []
        for it in spec[idx]:
            if it['name'] not in names: print('missing', idx + 1, it['name']); continue
            items.append({**it, 'spid': names[it['name']]})
        x = re.sub(r'<p:transition.*?</p:transition>|<p:timing>.*?</p:timing>', '', x, flags=re.S)
        add = TRANS[idx % len(TRANS)] if idx else '<p:transition spd="slow"><p:fade/></p:transition>'
        if items: add += build_timing(items, kinds)
        x = x.replace('</p:clrMapOvr>', '</p:clrMapOvr>' + add, 1) if '</p:clrMapOvr>' in x else x.replace('</p:cSld>', '</p:cSld>' + add, 1)
        data = x.encode('utf8')
    zout.writestr(info, data)
zout.close()
print('animated ->', out)
